begin;
select set_config('test.a',gen_random_uuid()::text,true);
select set_config('test.b',gen_random_uuid()::text,true);
select set_config('test.m',gen_random_uuid()::text,true);
select set_config('test.r',gen_random_uuid()::text,true);
select set_config('test.s',gen_random_uuid()::text,true);
select set_config('test.key',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('test.a')::uuid,'TESTE-sales-a@example.invalid'),(current_setting('test.b')::uuid,'TESTE-sales-b@example.invalid');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
select public.initialize_account();
select public.commerce_command(gen_random_uuid(),'fees','update',current_setting('test.a')::uuid,'{"debit_fee_percent":2,"credit_fee_percent":5.49}');
select public.material_command(gen_random_uuid(),'create',current_setting('test.m')::uuid,'{"name":"TESTE Cacau","kind":"ingredient","unit":"kg","package_quantity":1,"package_price_cents":3072}');
select public.recipe_command(gen_random_uuid(),'create',current_setting('test.r')::uuid,jsonb_build_object('name','TESTE Brigadeiro','yield_units',5,'indirect_percent',25,'fee_percent',5.49,'final_quantity',500,'final_unit','g','serving_unit','g','components',jsonb_build_array(jsonb_build_object('material_id',current_setting('test.m'),'quantity',500,'unit','g'))));
select set_config('test.base',jsonb_build_object('recipe_id',current_setting('test.r'),'quantity',1,'unit_price_cents',1000,'payment','credit','occurred_local','2026-10-20T23:59:59','anonymous',false,'customer_name','=TESTE Antigo','customer_phone','(11) 99999-9999')::text,true);
select set_config('test.payload',(current_setting('test.base')::jsonb||jsonb_build_object('quote_signature',public.sale_preview(null,current_setting('test.base')::jsonb)->>'signature'))::text,true);
select public.commerce_command(current_setting('test.key')::uuid,'sale','create',current_setting('test.s')::uuid,current_setting('test.payload')::jsonb);
select public.commerce_command(current_setting('test.key')::uuid,'sale','create',current_setting('test.s')::uuid,current_setting('test.payload')::jsonb);
do $$ declare r jsonb;v jsonb;d jsonb;i integer;begin
 r:=public.recipe_nutrition(current_setting('test.r')::uuid);
 if (r->>'ready')::boolean or jsonb_array_length(r->'rows')<>0 then raise exception 'TESTE ausência virou zero';end if;
 perform public.material_command(gen_random_uuid(),'update',current_setting('test.m')::uuid,'{"name":"TESTE Cacau","kind":"ingredient","unit":"kg","package_quantity":1,"package_price_cents":3072,"nutrition":{"base_unit":"g","source":"TESTE Rótulo conferido","energy_kcal":400,"carbohydrates_g":60,"total_sugars_g":50,"added_sugars_g":40,"proteins_g":10,"total_fat_g":5,"saturated_fat_g":2,"trans_fat_g":0,"fiber_g":3,"sodium_mg":20}}');
 perform public.recipe_command(gen_random_uuid(),'update',current_setting('test.r')::uuid,jsonb_build_object('name','TESTE Brigadeiro','yield_units',5,'indirect_percent',25,'fee_percent',5.49,'final_quantity',400,'final_unit','g','serving_quantity',20,'serving_unit','g','household_measure','1 doce','components',jsonb_build_array(jsonb_build_object('material_id',current_setting('test.m'),'quantity',500,'unit','g'))));
 r:=public.recipe_nutrition(current_setting('test.r')::uuid);
 if not (r->>'ready')::boolean or jsonb_array_length(r->'rows')<>11 then raise exception 'TESTE memória completa %',r;end if;
 select value into v from jsonb_array_elements(r->'rows') where value->>'key'='energy_kcal';
 if (v->>'total')::numeric<>2000 or (v->>'per100')::numeric<>500 or (v->>'portion')::numeric<>100 or (v->>'vd')::numeric<>5 then raise exception 'TESTE rendimento/porção %',v;end if;
 select value into v from jsonb_array_elements(r->'rows') where value->>'key'='energy_kj';if (v->>'per100')::numeric<>2092 or v->>'vd' is not null then raise exception 'TESTE energia auxiliar';end if;
 if (r->'ingredients'->0->>'used_base')::numeric<>500 or r->'ingredients'->0->>'source'<>'TESTE Rótulo conferido' then raise exception 'TESTE rastreabilidade';end if;
 select to_jsonb(t)||jsonb_build_object('components',(select jsonb_agg(jsonb_build_object('material_id',material_id,'quantity',quantity,'unit',unit)) from public.recipe_materials where recipe_id=t.id)) into d from public.recipes t where id=current_setting('test.r')::uuid;
 perform public.recipe_command(gen_random_uuid(),'update',current_setting('test.r')::uuid,d||'{"final_quantity":300}');
 if (public.recipe_nutrition(current_setting('test.r')::uuid)->>'ready')::boolean then raise exception 'TESTE massa incompatível';end if;
 perform public.recipe_command(gen_random_uuid(),'update',current_setting('test.r')::uuid,d);
 r:=public.account_export();
 if r->>'schema'<>'respiro-doce-account' or r->>'version'<>'1' or r->>'account_id'<>current_setting('test.a') or jsonb_array_length(r->'data'->'material_nutrition')<>1 then raise exception 'TESTE snapshot';end if;
 if jsonb_typeof(r->'data'->'sales'->0->'unit_cost')<>'string' or r->'data'->'sales'->0->>'production_cents'<>'384' then raise exception 'TESTE precisão/histórico';end if;
 if (r->'data'->'sales'->0) ? 'owner_id' or (r->'data') ? 'command_receipts' or (r->'data') ? 'auth' then raise exception 'TESTE campos internos';end if;
 r:=public.customers_export('=TESTE');if jsonb_array_length(r->'items')<>1 or r->'items'->0->>'phone'<>'+5511999999999' then raise exception 'TESTE filtro de nome';end if;
 if jsonb_array_length(public.customers_export('99999')->'items')<>1 or jsonb_array_length(public.customers_export('%')->'items')<>0 then raise exception 'TESTE filtro literal';end if;

end $$;
reset role;
insert into public.customers(id,owner_id,base_name,phone) select gen_random_uuid(),current_setting('test.a')::uuid,'TESTE Página '||lpad(i::text,4,'0'),'+55118888'||lpad(i::text,5,'0') from generate_series(1,1005) g(i);
set local role authenticated;
do $$ declare r jsonb;begin
 r:=public.customers_export('TESTE Página');if jsonb_array_length(r->'items')<>1005 or r->'items'->0->>'name'<>'TESTE Página 0001' or r->'items'->1004->>'name'<>'TESTE Página 1005' then raise exception 'TESTE limite/paginação/ordem';end if;
 if jsonb_array_length(public.account_export()->'data'->'customers')<>1006 then raise exception 'TESTE backup truncado';end if;
end $$;
do $$ declare milk uuid:=gen_random_uuid();pack uuid:=gen_random_uuid();egg uuid:=gen_random_uuid();r jsonb;v jsonb;payload jsonb;recipe jsonb;rev bigint;begin
 payload:='{"name":"TESTE Leite","kind":"ingredient","unit":"l","package_quantity":1,"package_price_cents":5000,"density_g_ml":1.2,"nutrition":{"base_unit":"g","source":"TESTE Leite fonte","energy_kcal":100,"carbohydrates_g":5,"total_sugars_g":0,"added_sugars_g":0,"proteins_g":3,"total_fat_g":4,"saturated_fat_g":1,"trans_fat_g":0,"fiber_g":0,"sodium_mg":20}}';
 perform public.material_command(gen_random_uuid(),'create',milk,payload);
 perform public.material_command(gen_random_uuid(),'create',pack,'{"name":"TESTE Caixa","kind":"packaging","unit":"un","package_quantity":10,"package_price_cents":1000}');
 recipe:=jsonb_build_object('name','TESTE Líquido','yield_units',10,'indirect_percent',25,'fee_percent',0,'final_quantity',120,'final_unit','g','serving_quantity',12,'serving_unit','g','household_measure','1 colher','components',jsonb_build_array(jsonb_build_object('material_id',milk,'quantity',100,'unit','ml'),jsonb_build_object('material_id',pack,'quantity',1,'unit','un')));
 perform public.recipe_command(gen_random_uuid(),'update',current_setting('test.r')::uuid,recipe);
 select revision into rev from public.account_sync_state;
 r:=public.recipe_nutrition(current_setting('test.r')::uuid);
 select value into v from jsonb_array_elements(r->'rows') where value->>'key'='energy_kcal';
 if not (r->>'ready')::boolean or jsonb_array_length(r->'ingredients')<>1 or (v->>'total')::numeric<>120 or (v->>'per100')::numeric<>100 then raise exception 'TESTE densidade/embalagem %',r;end if;
 if (select revision from public.account_sync_state)<>rev then raise exception 'TESTE leitura alterou revisão';end if;
 payload:=jsonb_set(payload,'{nutrition,base_unit}','"ml"');perform public.material_command(gen_random_uuid(),'update',milk,payload);
 recipe:=recipe||jsonb_build_object('final_quantity',100,'serving_quantity',10,'components',jsonb_build_array(jsonb_build_object('material_id',milk,'quantity',100,'unit','g')));
 perform public.recipe_command(gen_random_uuid(),'update',current_setting('test.r')::uuid,recipe);
 r:=public.recipe_nutrition(current_setting('test.r')::uuid);select value into v from jsonb_array_elements(r->'rows') where value->>'key'='energy_kcal';
 if not (r->>'ready')::boolean or abs((v->>'total')::numeric-100/1.2)>0.00000001 then raise exception 'TESTE conversão inversa';end if;
 payload:=jsonb_set(payload,'{nutrition,fiber_g}','null');perform public.material_command(gen_random_uuid(),'update',milk,payload);
 if (public.recipe_nutrition(current_setting('test.r')::uuid)->>'ready')::boolean then raise exception 'TESTE nutriente ausente aceito';end if;
 payload:=jsonb_set(payload,'{nutrition,source}','""');perform public.material_command(gen_random_uuid(),'update',milk,payload);
 if (public.recipe_nutrition(current_setting('test.r')::uuid)->>'ready')::boolean then raise exception 'TESTE fonte ausente';end if;
 payload:=jsonb_set(jsonb_set(payload,'{nutrition,source}','"Fonte"'),'{nutrition,fiber_g}','0');payload:=jsonb_set(payload,'{nutrition,added_sugars_g}','99');perform public.material_command(gen_random_uuid(),'update',milk,payload);
 if (public.recipe_nutrition(current_setting('test.r')::uuid)->>'ready')::boolean then raise exception 'TESTE coerência';end if;
 perform public.material_command(gen_random_uuid(),'create',egg,'{"name":"TESTE Ovo","kind":"ingredient","unit":"un","package_quantity":10,"package_price_cents":1000,"nutrition":{"base_unit":"g","source":"Fonte","energy_kcal":100,"carbohydrates_g":5,"total_sugars_g":0,"added_sugars_g":0,"proteins_g":3,"total_fat_g":4,"saturated_fat_g":1,"trans_fat_g":0,"fiber_g":0,"sodium_mg":20}}');
 recipe:=recipe||jsonb_build_object('components',jsonb_build_array(jsonb_build_object('material_id',egg,'quantity',1,'unit','un')));perform public.recipe_command(gen_random_uuid(),'update',current_setting('test.r')::uuid,recipe);
 r:=public.recipe_nutrition(current_setting('test.r')::uuid);if (r->>'ready')::boolean or jsonb_array_length(r->'rows')<>0 then raise exception 'TESTE equivalência ausente';end if;
end $$;
select set_config('request.jwt.claim.sub',current_setting('test.b'),true);select public.initialize_account();
do $$ begin
 if jsonb_array_length(public.account_export()->'data'->'sales')<>0 or jsonb_array_length(public.customers_export()->'items')<>0 then raise exception 'TESTE exportação cruzada';end if;
 begin perform public.recipe_nutrition(current_setting('test.r')::uuid);raise exception 'TESTE receita cruzada';exception when no_data_found then null;end;
end $$;
reset role;set local role anon;
do $$ begin
 begin perform public.account_export();raise exception 'TESTE backup anônimo';exception when insufficient_privilege then null;end;
 begin perform public.customers_export();raise exception 'TESTE clientes anônimos';exception when insufficient_privilege then null;end;
 begin perform public.recipe_nutrition(gen_random_uuid());raise exception 'TESTE nutrição anônima';exception when insufficient_privilege then null;end;
end $$;
reset role;rollback;
select 'Nutrição/exportação: ausência distinta de zero, rendimento, porção, kcal/kJ, rastreabilidade, snapshot exato, mais de 1000 clientes, filtros, ordem e isolamento aprovados. Testes revertidos.' as resultado;
